public class Customer{private long id;private String last;private String first;private String middle;private String address;private String card;private String account;public Customer(long id,String last,String first,String middle,String address,String card,String account){this.id=id;this.last=last;this.first=first;this.middle=middle;this.address=address;this.card=card;this.account=account;}public Customer(long id,String last){this(id,last,"F","M","A","0000000000000001","AC");}public long id(){return id;}public void id(long value){id=value;}public String last(){return last;}public void last(String value){last=value;}public String first(){return first;}public void first(String value){first=value;}public String middle(){return middle;}public void middle(String value){middle=value;}public String address(){return address;}public void address(String value){address=value;}public String card(){return card;}public void card(String value){card=value;}public String account(){return account;}public void account(String value){account=value;}public String toString(){return id+"|"+last+"|"+first+"|"+middle+"|"+address+"|"+card+"|"+account;}public static Customer[]sorted(Customer[]a){Customer[]out=a.clone();java.util.Arrays.sort(out,new java.util.Comparator<Customer>(){public int compare(Customer a,Customer b){int c=a.last.compareTo(b.last);return c;}});return out;}public static Customer[]range(Customer[]a,String lo,String hi){int count=0;for(Customer c:a)if(c.card.compareTo(lo)>=0&&c.card.compareTo(hi)<=0)count++;Customer[]out=new Customer[count];int i=0;for(Customer c:a)if(c.card.compareTo(lo)>=0&&c.card.compareTo(hi)<=0)out[i++]=c;return out;}}
